import{_ as a,o as n,c as i,a3 as l}from"./chunks/framework.MGD2uYU7.js";const r=JSON.parse('{"title":"SC-20 — Dashboard","description":"","frontmatter":{"title":"SC-20 — Dashboard"},"headers":[],"relativePath":"wireframes/user/sc-20-dashboard.md","filePath":"wireframes/user/sc-20-dashboard.md","lastUpdated":null}'),c={name:"wireframes/user/sc-20-dashboard.md"};function t(p,s,e,d,o,h){return n(),i("div",null,[...s[0]||(s[0]=[l('<h1 id="sc-20-—-dashboard-thanh-vien" tabindex="-1">SC-20 — Dashboard thành viên <a class="header-anchor" href="#sc-20-—-dashboard-thanh-vien" aria-label="Permalink to &quot;SC-20 — Dashboard thành viên&quot;">​</a></h1><p><span class="wf-badge info">Route: /dashboard</span> <span class="wf-badge muted">Guard: USER · Nguồn: docs/05 §3 SC-20 · docs/08 BR-KYC-08 · docs/06 §3 endpoint 8</span></p><p><strong>Ai xem màn này</strong>: Thành viên đã đăng nhập (role USER) — cả người mới tinh (chưa làm gì) lẫn người đang vận hành tin/phiên/đơn. ADMIN không dùng màn này (layout riêng SC-40). <strong>Mục đích / cảm xúc thiết kế</strong>: &quot;trạm điều khiển cá nhân&quot; — trả lời 3 câu trong 5 giây: <em>Tôi cần làm gì tiếp theo? · Tài sản/tin của tôi ra sao? · Có gì gấp cần xử lý (tiền, phiên, duyệt)?</em> Không đồ thị marketing, không số vô nghĩa. <strong>Ví dụ số dùng trong bản vẽ</strong>: <code>Nguyễn Văn Demo</code> (NĐ) · KYC APPROVED 08/10/2026 · gói FREE hạn mức 2 tin (đang dùng 1/2) · 3 tin: 1 LISTED (<code>AB-05.02</code> giá <code>1.250.000.000 ₫</code>), 1 IN_REVIEW, 1 DRAFT · đang tham gia phiên căn <code>CT2-A18.05</code> dưới bí danh <code>TV-7F2A</code> · 🔔 2 thông báo chưa đọc.</p><h2 id="_1-desktop-—-dashboard-đay-đu-kyc-đa-approved-co-du-lieu" tabindex="-1">1. Desktop — dashboard đầy đủ (KYC đã APPROVED, có dữ liệu) <a class="header-anchor" href="#_1-desktop-—-dashboard-đay-đu-kyc-đa-approved-co-du-lieu" aria-label="Permalink to &quot;1. Desktop — dashboard đầy đủ (KYC đã APPROVED, có dữ liệu)&quot;">​</a></h2><div class="wf"><div class="wf-screen"><div class="wf-browser-bar"><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-url">anphuc.vn/dashboard</span></div><div class="wf-body"><div class="wf-header"><span class="wf-logo">AnPhuc</span><span class="wf-nav"><span>Mua nhà</span><span>Đấu giá</span><span>Bảng gói</span><span>Hướng dẫn</span></span><span class="wf-header-actions"><span class="wf-bell">🔔<span class="count">2</span></span><span class="wf-avatar">NĐ</span></span></div><div class="wf-container"><div class="wf-row between middle" style="margin-bottom:12px;"><div class="wf-col" style="gap:2px;"><span class="wf-title xl">Xin chào, Nguyễn Văn Demo</span><span class="wf-row middle" style="gap:8px;"><span class="wf-badge ok">Đã xác minh CCCD ✓</span><span class="wf-badge muted">Gói FREE · 1/2 tin</span></span></div><span class="wf-btn primary">＋ Đăng tin mới → SC-22 <span class="wf-callout">1</span></span></div><div class="wf-row" style="align-items:stretch;"><div class="wf-grow wf-col" style="gap:12px;"><div class="wf-card"><div class="pad wf-col" style="gap:10px;"><span class="wf-title">Bắt đầu cùng AnPhuc <span class="wf-callout">2</span></span><div class="wf-steps"><span class="wf-step done">1 · Xác minh CCCD ✓</span><span class="wf-step active">2 · Đăng tin đầu tiên</span><span class="wf-step">3 · Nâng cấp VIP (tùy chọn)</span></div><span class="wf-checkbox checked"><span class="wf-text">Xác minh danh tính (CCCD) — đã duyệt 08/10/2026 09:30</span></span><div class="wf-row between middle"><span class="wf-checkbox"><span class="wf-text">Đăng tin bán đầu tiên — hạn mức FREE 2 tin</span></span><span class="wf-btn sm primary">Đăng tin → SC-22</span></div><div class="wf-row between middle"><span class="wf-checkbox"><span class="wf-text">Tìm hiểu gói VIP — thêm tin, badge nổi bật</span></span><span class="wf-btn sm ghost">Xem bảng gói → SC-07</span></div></div></div><div class="wf-grid"><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><div class="wf-row between middle"><span class="wf-title">Tin của tôi</span><span class="wf-small wf-accent">Xem tất cả → SC-23</span></div><div class="wf-row" style="gap:16px;"><div class="wf-col" style="gap:0;"><span class="wf-money lg">1</span><span class="wf-small">Đang bán</span></div><div class="wf-col" style="gap:0;"><span class="wf-money lg">1</span><span class="wf-small">Chờ duyệt</span></div><div class="wf-col" style="gap:0;"><span class="wf-money lg">1</span><span class="wf-small">Nháp</span></div><div class="wf-col" style="gap:0;"><span class="wf-money lg">0</span><span class="wf-small">Đã bán</span></div></div><span class="wf-small">Hạn mức FREE: 1/2 tin đang bán — <b class="wf-accent">Nâng cấp VIP: 500.000 ₫/10 tin/30 ngày → SC-26</b> <span class="wf-callout">3</span></span></div></div><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><div class="wf-row between middle"><span class="wf-title">Phiên đã đăng ký</span><span class="wf-small wf-accent">SC-24 →</span></div><div class="wf-col" style="gap:4px;"><span class="wf-badge danger live">🔴 ĐANG DIỄN RA</span><span class="wf-text">Phiên DGA-2026-0001 · căn <b>CT2-A18.05</b> — NOXH HP-380</span><span class="wf-small">Bạn ra giá dưới bí danh <b>TV-7F2A</b> · cọc đã nộp <b class="wf-money">90.000.000 ₫</b></span><span class="wf-btn sm primary block">Vào phiên ngay → SC-06 <span class="wf-callout">4</span></span></div></div></div><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><div class="wf-row between middle"><span class="wf-title">Đơn chờ thanh toán</span><span class="wf-small wf-accent">SC-25 →</span></div><div class="wf-empty" style="padding:16px 12px;"><span class="icon">🧾</span><span class="wf-small">Chưa có đơn nào chờ thanh toán</span></div><span class="wf-small wf-muted">Nếu trúng giá, đơn sẽ hiện ở đây kèm <b>đồng hồ 24 giờ</b> — quá hạn mất cọc (xem biến thể mục 4)</span></div></div><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><div class="wf-row between middle"><span class="wf-title">Thông báo gần đây</span><span class="wf-small wf-accent">Xem tất cả → SC-28</span></div><div class="wf-col" style="gap:6px;"><div class="wf-row between"><span class="wf-text">● Nhắc lịch: phiên căn CT2-A18.05 đang diễn ra</span><span class="wf-small">10/10 14:00</span></div><div class="wf-row between"><span class="wf-text">● Tin AB-05.02 đã được duyệt — đang hiển thị</span><span class="wf-small">10/10 08:15</span></div><div class="wf-row between"><span class="wf-text wf-muted">Hồ sơ KYC của bạn đã được duyệt</span><span class="wf-small">08/10 09:30</span></div></div><span class="wf-small wf-muted">● = chưa đọc — đồng bộ số chuông 🔔 trên header <span class="wf-callout">5</span></span></div></div></div></div></div></div><div class="wf-footer"><span>AnPhucRealEstate — sàn NOXH được vận hành bởi An Phuc</span><span>Quy chế đấu giá</span><span>CSKH 1900-xxx</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích hành vi (trace: docs/05 §3 SC-20 · docs/08 BR-KYC/BR-AU/BR-PKG)</div><ol><li><span class="num">1</span><span><b>CTA chính đổi theo trạng thái KYC</b>: APPROVED → &quot;Đăng tin mới&quot;; chưa xác minh → &quot;Xác minh ngay&quot; (mục 2). Nút disable + tooltip khi tài khoản SUSPENDED (mọi mutation 403). <span class="ref">BR-KYC-08</span> <span class="ref">BR-IDT-07</span></span></li><li><span class="num">2</span><span><b>Checklist onboarding</b> cố định 3 bước: KYC → đăng tin → (mua VIP, tùy chọn). Bước KYC là điều kiện tiên quyết cho đăng tin/đăng ký đấu giá/đặt lịch — chưa xong thì CTA các bước sau trỏ về SC-21 thay vì SC-22. Card tự ẩn khi user đã hoàn thành cả 3 (không chiếm chỗ mãi). <span class="ref">BR-KYC-08</span> <span class="ref">docs/05 §3 SC-20</span></span></li><li><span class="num">3</span><span><b>Quota tin hiển thị thật</b>: đếm tin LISTED+RESERVED+SOLD trong 30 ngày theo BR-PKG-02; chạm hạn → link upsell VIP (bảng giá BR-PKG-01: FREE 0đ/2 tin · VIP_STANDARD 500.000đ/10 tin · VIP_PRO 1.500.000đ/50 tin). <span class="ref">BR-PKG-01/02</span> <span class="ref">FR-HS-10</span></span></li><li><span class="num">4</span><span>Widget phiên: chỉ hiện phiên có registration của user (PENDING_DEPOSIT → nhắc nộp cọc kèm deadline; ACTIVE → badge LIVE khi phiên đang chạy). Bí danh TV-7F2A hiện cho chính chủ. <span class="ref">BR-AU-20</span> <span class="ref">BR-AU-07</span></span></li><li><span class="num">5</span><span>Dữ liệu màn: <code>GET /users/me/summary</code> (endpoint 8) + unread count <code>GET /notifications/unread-count</code>. Chuông header và widget đọc cùng nguồn — mark-read ở SC-28 thì cả hai cập nhật. <span class="ref">docs/06 §3</span> <span class="ref">FR-NTF-06</span></span></li></ol></div><h2 id="_2-desktop-—-bien-the-theo-trang-thai-kyc-cta-banner" tabindex="-1">2. Desktop — biến thể theo trạng thái KYC (CTA + banner) <a class="header-anchor" href="#_2-desktop-—-bien-the-theo-trang-thai-kyc-cta-banner" aria-label="Permalink to &quot;2. Desktop — biến thể theo trạng thái KYC (CTA + banner)&quot;">​</a></h2><div class="wf"><div class="wf-grid cols-3"><div class="wf-col"><span class="wf-state-label">TRẠNG THÁI: KYC = NONE (CHƯA XÁC MINH)</span><div class="wf-card"><div class="pad wf-col" style="gap:10px;"><div class="wf-toast warn">Bạn cần xác minh danh tính (CCCD) trước khi thao tác này <span class="wf-callout warn">6</span></div><div class="wf-steps"><span class="wf-step active">1 · Xác minh CCCD</span><span class="wf-step">2 · Đăng tin đầu tiên</span><span class="wf-step">3 · Nâng cấp VIP</span></div><span class="wf-small">Chưa xác minh thì chưa thể: đăng tin · đăng ký đấu giá · đặt lịch xem nhà.</span><span class="wf-btn primary block">Xác minh ngay → SC-21</span><span class="wf-btn disabled block">＋ Đăng tin mới (khóa)</span></div></div></div><div class="wf-col"><span class="wf-state-label">TRẠNG THÁI: KYC = PENDING (ĐANG CHỜ DUYỆT)</span><div class="wf-card"><div class="pad wf-col" style="gap:10px;"><div class="wf-row between middle"><span class="wf-badge warn">KYC đang chờ duyệt</span><span class="wf-small">nộp lúc 10/10/2026 09:30 (GMT+7)</span></div><div class="wf-note">Hồ sơ đang được duyệt — kết quả chậm nhất <b>12/10/2026 09:30</b> (SLA ≤48 giờ). Trong lúc chờ bạn vẫn xem tin và phiên bình thường. <span class="wf-callout">7</span></div><span class="wf-btn ghost block">Xem hồ sơ đã nộp → SC-21</span><span class="wf-btn disabled block">＋ Đăng tin mới (mở sau khi duyệt)</span></div></div></div><div class="wf-col"><span class="wf-state-label">TRẠNG THÁI: KYC = REJECTED (BỊ TỪ CHỐI)</span><div class="wf-card"><div class="pad wf-col" style="gap:10px;"><div class="wf-toast danger">Hồ sơ xác minh bị từ chối — xem lý do và nộp lại <span class="wf-callout danger">8</span></div><span class="wf-small">Lý do (nguyên văn): &quot;Ảnh mặt sau bị mờ phần số CCCD — chụp lại trên nền phẳng, đủ sáng, không che góc.&quot;</span><span class="wf-btn primary block">Xem lý do &amp; nộp lại → SC-21</span><span class="wf-small wf-muted">Còn 1/3 lần nộp trong 30 ngày — quá giới hạn phải qua CSKH 1900-xxx.</span></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích biến thể KYC</div><ol><li><span class="num">6</span><span>Banner dùng <b>nguyên văn</b> message <code>KYC_REQUIRED</code> docs/06 §5. CTA chính của dashboard đổi thành &quot;Xác minh ngay&quot;; các nút nghiệp vụ (đăng tin…) chuyển disabled kèm giải thích — không ẩn hẳn để user không bị &quot;mất chức năng không lý do&quot;. <span class="ref">docs/06 §5</span> <span class="ref">BR-KYC-08</span></span></li><li><span class="num">7</span><span>PENDING: hiện ngày hẹn theo SLA duyệt KYC ≤48 giờ — không tạo cảm giác bị treo vô hạn. <span class="ref">BR-ADM-03</span> <span class="ref">UC-02 MF</span></span></li><li><span class="num">8</span><span>REJECTED: lý do hiển thị nguyên văn từ ADMIN (10–500 ký tự) + đếm số lần nộp còn lại; chi tiết banner/nộp lại vẽ ở SC-21 mục 5. <span class="ref">BR-KYC-04</span> <span class="ref">BR-KYC-06</span></span></li></ol></div><h2 id="_3-desktop-—-user-moi-tinh-onboarding-empty-skeleton-loading" tabindex="-1">3. Desktop — user mới tinh (onboarding empty) + skeleton loading <a class="header-anchor" href="#_3-desktop-—-user-moi-tinh-onboarding-empty-skeleton-loading" aria-label="Permalink to &quot;3. Desktop — user mới tinh (onboarding empty) + skeleton loading&quot;">​</a></h2><div class="wf"><div class="wf-grid"><div class="wf-col"><span class="wf-state-label">TRẠNG THÁI: EMPTY — USER VỪA ĐĂNG KÝ (SC-10 →)</span><div class="wf-col" style="gap:12px;"><div class="wf-card"><div class="pad wf-col" style="gap:10px;"><span class="wf-title lg">Chào mừng Nguyễn Văn Demo 👋</span><div class="wf-empty"><span class="icon">🏠</span><b>Bạn chưa có hoạt động nào trên sàn</b><div class="wf-small" style="margin:6px 0 12px;">Bắt đầu với 3 bước — bước 1 là bắt buộc để dùng mọi tính năng mua/bán/đấu giá</div><span class="wf-btn primary lg">BƯỚC 1 — XÁC MINH DANH TÍNH (CCCD) → SC-21 <span class="wf-callout">9</span></span></div></div></div><div class="wf-grid"><div class="wf-card"><div class="pad"><span class="wf-title">Tin của tôi</span><div class="wf-empty" style="padding:14px 10px;"><span class="icon">📄</span><span class="wf-small">0 tin — hạn mức FREE 0/2</span></div></div></div><div class="wf-card"><div class="pad"><span class="wf-title">Phiên đã đăng ký</span><div class="wf-empty" style="padding:14px 10px;"><span class="icon">⏱</span><span class="wf-small">Chưa đăng ký phiên nào — xem phiên sắp mở → SC-05</span></div></div></div></div></div></div><div class="wf-col"><span class="wf-state-label">TRẠNG THÁI: LOADING — SKELETON</span><div class="wf-col" style="gap:12px;"><div class="wf-skeleton" style="height:76px;"></div><div class="wf-skeleton" style="height:130px;"></div><div class="wf-grid"><div class="wf-skeleton" style="height:110px;"></div><div class="wf-skeleton" style="height:110px;"></div><div class="wf-skeleton" style="height:110px;"></div><div class="wf-skeleton" style="height:110px;"></div></div><span class="wf-small wf-muted">Skeleton theo đúng khung layout (greeting + checklist + 4 widget) — không spinner toàn trang. <span class="wf-callout">10</span></span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích empty + loading</div><ol><li><span class="num">9</span><span>Empty-state onboarding: CTA duy nhất, to, trỏ bước 1 (KYC) — không bày 5 lối đi khi user chưa làm được gì. Widget rỗng vẫn hiện khung + link khám phá (xem phiên sắp mở SC-05) để không &quot;chết&quot;. <span class="ref">docs/05 §1.4</span> <span class="ref">BR-KYC-08</span></span></li><li><span class="num">10</span><span>4 trạng thái nền của màn: <b>Loading</b> = skeleton như trên; <b>Error</b> = hộp lỗi + traceId + nút &quot;Thử lại&quot; (component ErrorState); <b>Empty</b> = onboarding; <b>Data</b> = mục 1. <span class="ref">docs/05 §1.4</span></span></li></ol></div><h2 id="_4-widget-đon-cho-thanh-toan-—-bien-the-khi-trung-gia-co-đong-ho-24h" tabindex="-1">4. Widget &quot;Đơn chờ thanh toán&quot; — biến thể khi trúng giá (có đồng hồ 24h) <a class="header-anchor" href="#_4-widget-đon-cho-thanh-toan-—-bien-the-khi-trung-gia-co-đong-ho-24h" aria-label="Permalink to &quot;4. Widget &quot;Đơn chờ thanh toán&quot; — biến thể khi trúng giá (có đồng hồ 24h)&quot;">​</a></h2><div class="wf"><div class="wf-col" style="max-width:480px;"><span class="wf-state-label">TRẠNG THÁI: CÓ ĐƠN PENDING — ĐẾM NGƯỢC 24 GIỜ</span><div class="wf-card" style="border-width:2px;border-color:var(--wf-danger);"><div class="pad wf-col" style="gap:10px;"><div class="wf-row between middle"><span class="wf-title">🎉 Bạn trúng giá căn CT2-A18.05</span><span class="wf-badge danger">Cần thanh toán</span></div><div class="wf-center"><span class="wf-small">THỜI HẠN THANH TOÁN CÒN LẠI</span><br><span class="wf-countdown">23 : 41 : 07</span></div><div class="wf-col" style="gap:6px;"><div class="wf-row between"><span class="wf-text">Giá trúng</span><span class="wf-money">1.950.000.000 ₫</span></div><div class="wf-row between"><span class="wf-text">Phí đấu giá (1,5%)</span><span class="wf-money">+29.250.000 ₫</span></div><div class="wf-row between"><span class="wf-text">Cọc đã nộp</span><span class="wf-money">−90.000.000 ₫</span></div><div class="wf-row between" style="border-top:2px solid var(--wf-ink);padding-top:6px;"><span class="wf-strong">Còn phải trả</span><span class="wf-money lg">1.889.250.000 ₫</span></div></div><span class="wf-btn primary lg block">THANH TOÁN NGAY → SC-25 <span class="wf-callout" style="background:#fff;color:var(--wf-accent);">11</span></span><span class="wf-small wf-danger-text">Quá hạn 15/10/2026 14:32 (GMT+7): mất cọc 90.000.000 ₫ + tạm ngưng quyền đấu giá</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">11</span><span>Widget đơn chờ = bản thu gọn của card settlement (SC-25/SC-06 dùng lại cùng breakdown — quy tắc &quot;không số gộp&quot;): đủ 4 dòng tiền, hạn chót tuyệt đối <code>dd/MM/yyyy HH:mm</code> (GMT+7), countdown đồng bộ giờ server (offset <code>X-Server-Time</code>, không tin đồng hồ máy khách). Viền đỏ + widget đẩy lên đầu grid khi có đơn PENDING. <span class="ref">BR-AU-14/15</span> <span class="ref">BR-AU-16</span> <span class="ref">docs/05 §1.6</span></span></li></ol></div><h2 id="_5-mobile-360px-—-dashboard-xep-cot" tabindex="-1">5. Mobile 360px — dashboard xếp cột <a class="header-anchor" href="#_5-mobile-360px-—-dashboard-xep-cot" aria-label="Permalink to &quot;5. Mobile 360px — dashboard xếp cột&quot;">​</a></h2><div class="wf"><div class="wf-row" style="justify-content:center;gap:20px;flex-wrap:wrap;"><div><span class="wf-state-label">MOBILE — DASHBOARD (ĐÃ KYC)</span><div class="wf-mobile"><div class="wf-mobile-bar"><span>9:41</span><span>▮▮▮ ⌁ ▰</span></div><div class="wf-header" style="padding:8px 12px;"><span class="wf-logo">AnPhuc</span><span class="wf-header-actions"><span class="wf-bell">🔔<span class="count">2</span></span><span class="wf-avatar">NĐ</span></span></div><div class="wf-container" style="padding:12px;"><div class="wf-col" style="gap:10px;"><div class="wf-row between middle"><span class="wf-title">Xin chào, Nguyễn Văn Demo</span><span class="wf-badge ok">KYC ✓</span></div><span class="wf-btn primary block">＋ Đăng tin mới</span><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><span class="wf-title">Bắt đầu cùng AnPhuc</span><div class="wf-steps"><span class="wf-step done">1 ✓</span><span class="wf-step active">2 · Đăng tin</span><span class="wf-step">3 · VIP</span></div><span class="wf-btn sm primary block">Đăng tin đầu tiên → SC-22</span></div></div><div class="wf-card" style="border-width:2px;border-color:var(--wf-danger);"><div class="pad wf-col" style="gap:6px;"><div class="wf-row between middle"><span class="wf-title">Phiên của bạn</span><span class="wf-badge danger live">🔴 LIVE</span></div><span class="wf-text">CT2-A18.05 · bí danh TV-7F2A</span><span class="wf-btn sm primary block">Vào phiên → SC-06</span></div></div><div class="wf-card"><div class="pad wf-col" style="gap:6px;"><div class="wf-row between middle"><span class="wf-title">Tin của tôi</span><span class="wf-small wf-accent">SC-23 →</span></div><div class="wf-row" style="gap:12px;"><div class="wf-col" style="gap:0;"><span class="wf-money">1</span><span class="wf-small">Đang bán</span></div><div class="wf-col" style="gap:0;"><span class="wf-money">1</span><span class="wf-small">Chờ duyệt</span></div><div class="wf-col" style="gap:0;"><span class="wf-money">1</span><span class="wf-small">Nháp</span></div></div><span class="wf-small">FREE 1/2 tin · <b class="wf-accent">Nâng VIP →</b></span></div></div><div class="wf-card"><div class="pad wf-col" style="gap:6px;"><div class="wf-row between middle"><span class="wf-title">Thông báo</span><span class="wf-small wf-accent">SC-28 →</span></div><span class="wf-small">● Phiên CT2-A18.05 đang diễn ra</span><span class="wf-small">● Tin AB-05.02 đã được duyệt</span></div></div></div></div></div></div><div><span class="wf-state-label">MOBILE — USER MỚI (ONBOARDING)</span><div class="wf-mobile"><div class="wf-mobile-bar"><span>9:41</span><span>▮▮▮ ⌁ ▰</span></div><div class="wf-header" style="padding:8px 12px;"><span class="wf-logo">AnPhuc</span><span class="wf-header-actions"><span class="wf-bell">🔔</span><span class="wf-avatar">NĐ</span></span></div><div class="wf-container" style="padding:12px;"><div class="wf-col" style="gap:10px;"><span class="wf-title">Chào mừng Nguyễn Văn Demo</span><div class="wf-empty" style="padding:24px 12px;"><span class="icon">🏠</span><b>Chưa có hoạt động nào</b><div class="wf-small" style="margin:6px 0 12px;">Bước 1 bắt buộc: xác minh danh tính (CCCD)</div><span class="wf-btn primary block">XÁC MINH NGAY → SC-21</span></div><div class="wf-note">Sau khi xác minh: đăng tin bán (FREE 2 tin), đăng ký đấu giá, đặt lịch xem nhà.</div></div></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích mobile</div><ol><li><span class="num">M</span><span>Thứ tự ưu tiên mobile: CTA theo KYC → checklist → phiên LIVE/đơn 24h (viền đỏ, đẩy cao) → tin của tôi → thông báo. Widget nào có &quot;tiền hoặc thời gian gấp&quot; luôn đứng trên widget thống kê.</span></li></ol></div><h2 id="_6-checklist-designer-khi-dung-figma-cho-sc-20" tabindex="-1">6. Checklist designer khi dựng Figma cho SC-20 <a class="header-anchor" href="#_6-checklist-designer-khi-dung-figma-cho-sc-20" aria-label="Permalink to &quot;6. Checklist designer khi dựng Figma cho SC-20&quot;">​</a></h2><ul><li>[ ] Đủ layout: desktop (checklist + grid 2×2 widget) / mobile 360 (xếp cột) / tablet 768 (grid 2 cột)</li><li>[ ] Đủ trạng thái: data đầy đủ · 3 biến thể KYC (NONE/PENDING/REJECTED đổi CTA + banner) · onboarding empty · skeleton · error+traceId · widget đơn PENDING có countdown 24h · SUSPENDED banner</li><li>[ ] CTA chính đổi đúng theo KYC: chưa xác minh → &quot;Xác minh ngay&quot;; APPROVED → &quot;Đăng tin&quot;; message KYC_REQUIRED nguyên văn docs/06 §5</li><li>[ ] Countdown đồng hồ 24h đồng bộ giờ server (X-Server-Time); hạn chót tuyệt đối <code>dd/MM/yyyy HH:mm</code> (GMT+7); tiền <code>1.889.250.000 ₫</code></li><li>[ ] Quota FREE hiển thị <code>1/2 tin</code> đúng quy tắc đếm BR-PKG-02 (LISTED+RESERVED+SOLD ≤30 ngày)</li><li>[ ] Không emoji icon trong UI production (🔔/🏠/🧾/👋 trong wireframe là placeholder vị trí — thay icon set thật)</li><li>[ ] Accessibility: contrast AA cho badge đỏ trên nền trắng, focus ring các CTA, widget tiền có aria-live khi countdown cập nhật (note cho FE)</li></ul><div class="info custom-block"><p class="custom-block-title">Góp ý màn này?</p><p>Comment ngay bên dưới — ghi rõ khu vực (số callout) và đề xuất. Thay đổi nghiệp vụ (vd thứ tự bước onboarding, quota) cần PM duyệt trên docs/08 trước.</p></div>',21)])])}const g=a(c,[["render",t]]);export{r as __pageData,g as default};
